import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'app-empty-state',
  templateUrl: './empty-state.component.html',
  styleUrls: ['./empty-state.component.css']
})
export class EmptyStateComponent {
  @Input() icon = 'fa-regular fa-folder-open';
  @Input() title = 'No data found';
  @Input() message = 'We could not find any records matching your criteria.';
  @Input() actionText?: string;
  @Input() actionRoute?: string;
  @Output() actionClick = new EventEmitter<void>();

  onAction(): void {
    this.actionClick.emit();
  }
}
<div class="empty-state-wrapper">
  <div class="empty-icon-circle">
    <i [class]="icon"></i>
  </div>
  <h3 class="empty-title">{{ title }}</h3>
  <p class="empty-message">{{ message }}</p>

  <div *ngIf="actionText" class="empty-action">
    <a *ngIf="actionRoute" [routerLink]="actionRoute" class="btn btn-primary">
      {{ actionText }}
    </a>
    <button *ngIf="!actionRoute" (click)="onAction()" class="btn btn-primary">
      {{ actionText }}
    </button>
  </div>
</div>
